import { sql } from "drizzle-orm";
import { bigint, integer, timestamp, uuid } from "drizzle-orm/pg-core";

/** Primary key: random UUID generated by Postgres (gen_random_uuid, PG13+). */
export const id = () => uuid("id").primaryKey().defaultRandom();

/** Monetary amount in minor units (paise/cents). bigint avoids overflow in aggregates. */
export const money = (name: string) => bigint(name, { mode: "number" });

/** Rate in basis points (500 = 5 %). */
export const bps = (name: string) => integer(name);

export const tstz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

export const timestamps = {
  createdAt: tstz("created_at").notNull().defaultNow(),
  updatedAt: tstz("updated_at")
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

/** Optimistic concurrency version, incremented on every update. */
export const version = () => integer("version").notNull().default(1);

export const softDelete = { deletedAt: tstz("deleted_at") };

export const inList = (column: string, values: readonly string[]) =>
  sql.raw(`${column} in (${values.map((v) => `'${v.replace(/'/g, "''")}'`).join(", ")})`);
